import{_ as a,o as e,c as n,ag as o}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"DSP documentation – structure and how to find module docs","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),t={name:"README.md"};function d(i,s,l,r,c,p){return e(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="dsp-documentation-–-structure-and-how-to-find-module-docs" tabindex="-1">DSP documentation – structure and how to find module docs <a class="header-anchor" href="#dsp-documentation-–-structure-and-how-to-find-module-docs" aria-label="Permalink to &quot;DSP documentation – structure and how to find module docs&quot;">​</a></h1><p>This file explains <strong>how docs are organized</strong> so you always know <strong>which module a doc belongs to</strong> and where to find deep (file-by-file, query-by-query) documentation.</p><hr><h2 id="doc-layout" tabindex="-1">Doc layout <a class="header-anchor" href="#doc-layout" aria-label="Permalink to &quot;Doc layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├── README.md                    ← You are here: structure + &quot;which module is this&quot;</span></span>
<span class="line"><span>├── DEVELOPER_INDEX.md           ← Entry point: repo overview + links to all docs</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 01_ADMIN_DASHBOARD.md        ← Top-level phase docs (overview of whole area)</span></span>
<span class="line"><span>├── 02_STUDENT_DASHBOARD.md      (planned)</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── modules/                     ← DEEP module docs (each file, query, mutation, typeDef)</span></span>
<span class="line"><span>│   ├── README.md                ← Index: list of all modules and their docs</span></span>
<span class="line"><span>│   ├── admin-dashboard/         ← Module: Admin Dashboard</span></span>
<span class="line"><span>│   │   ├── README.md            ← What this module is + list of sub-module docs</span></span>
<span class="line"><span>│   │   ├── overview-analytics.md</span></span>
<span class="line"><span>│   │   ├── admin-access.md</span></span>
<span class="line"><span>│   │   ├── documents.md</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   ├── student-dashboard/</span></span>
<span class="line"><span>│   ├── teacher-dashboard/</span></span>
<span class="line"><span>│   ├── auth/</span></span>
<span class="line"><span>│   └── payments/</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── BUSINESS_RULES_*.md          ← Other reference docs (Stripe, handover, etc.)</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><hr><h2 id="how-to-know-which-module-doc-is-this" tabindex="-1">How to know “which module doc is this?” <a class="header-anchor" href="#how-to-know-which-module-doc-is-this" aria-label="Permalink to &quot;How to know “which module doc is this?”&quot;">​</a></h2><ul><li><p><strong>Folder name = area/module</strong></p><ul><li><code>modules/admin-dashboard/</code> → <strong>Admin Dashboard</strong></li><li><code>modules/student-dashboard/</code> → <strong>Student Dashboard</strong></li><li><code>modules/teacher-dashboard/</code> → <strong>Instructor/Teacher Dashboard</strong></li><li><code>modules/auth/</code> → <strong>Authentication</strong></li><li><code>modules/payments/</code> → <strong>Payments &amp; Stripe</strong></li><li>etc.</li></ul></li><li><p><strong>File name = feature or sub-module</strong></p><ul><li><code>overview-analytics.md</code> → Admin Overview / Analytics screen</li><li><code>admin-access.md</code> → Admin Access (signup links)</li><li><code>signin.md</code> → Sign-in flow</li><li><code>checkout.md</code> → Checkout / payment flow</li></ul></li><li><p><strong>Full path = unique module doc</strong></p><ul><li><code>modules/admin-dashboard/overview-analytics.md</code> = <strong>Admin Dashboard → Overview/Analytics</strong></li><li><code>modules/auth/signin.md</code> = <strong>Auth → Sign-in</strong></li></ul></li></ul><p>So: <strong>folder = module</strong>, <strong>file = feature inside that module</strong>. Every doc’s path tells you exactly which module it is.</p><hr><h2 id="two-levels-of-documentation" tabindex="-1">Two levels of documentation <a class="header-anchor" href="#two-levels-of-documentation" aria-label="Permalink to &quot;Two levels of documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Where</th><th>What it covers</th></tr></thead><tbody><tr><td><strong>Top-level (phase)</strong></td><td><code>docs/01_ADMIN_DASHBOARD.md</code>, etc.</td><td>High-level: routes, screens, main components, main GraphQL and backend. Good for “what exists” and navigation.</td></tr><tr><td><strong>Deep (module)</strong></td><td><code>docs/modules/&lt;module&gt;/&lt;feature&gt;.md</code></td><td>Detail: <strong>every</strong> code file, <strong>every</strong> query/mutation/typeDef, resolvers, frontend–API integration. Good for “how does this exact feature work?”</td></tr></tbody></table><p>Use <strong>phase docs</strong> to get the big picture; use <strong>module docs</strong> when you need to touch or understand a specific feature in depth (e.g. “Admin Overview Analytics” or “Signup links”).</p><hr><h2 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h2><ul><li><strong>Start here:</strong> <a href="./DEVELOPER_INDEX">DEVELOPER_INDEX.md</a></li><li><strong>All deep module docs:</strong> <a href="./modules/README">modules/README.md</a></li><li><strong>Admin dashboard deep docs:</strong> <a href="./modules/admin-dashboard/README">modules/admin-dashboard/README.md</a></li></ul><h2 id="docs-ui" tabindex="-1">Docs UI <a class="header-anchor" href="#docs-ui" aria-label="Permalink to &quot;Docs UI&quot;">​</a></h2><p>This documentation can now be rendered as a VitePress site from the <code>docs/</code> folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div>`,19)])])}const m=a(t,[["render",d]]);export{u as __pageData,m as default};
